// Employee Onboarding Workflow: core logic (ported from main.py)
const TEMPLATES = {
 "common": [
  {
   "task": "Send offer letter and contract to {name}",
   "owner": "HR",
   "offset": -10
  },
  {
   "task": "Collect ID, bank details and NHF/pension forms",
   "owner": "HR",
   "offset": -5
  },
  {
   "task": "Create email and Slack accounts",
   "owner": "IT",
   "offset": -3
  },
  {
   "task": "Prepare 30-60-90 day plan",
   "owner": "manager",
   "offset": -2
  },
  {
   "task": "Day one welcome and introductions",
   "owner": "manager",
   "offset": 0
  },
  {
   "task": "Company policies walkthrough",
   "owner": "HR",
   "offset": 1
  },
  {
   "task": "First 1:1 with manager",
   "owner": "manager",
   "offset": 3
  },
  {
   "task": "30-day check-in",
   "owner": "manager",
   "offset": 22
  }
 ],
 "department": {
  "Engineering": [
   {
    "task": "Grant GitHub and cloud access",
    "owner": "IT",
    "offset": -1
   },
   {
    "task": "Pair on first small task",
    "owner": "manager",
    "offset": 2
   }
  ],
  "Sales": [
   {
    "task": "Create CRM seat",
    "owner": "IT",
    "offset": -1
   },
   {
    "task": "Shadow three sales calls",
    "owner": "manager",
    "offset": 4
   }
  ]
 },
 "remote": [
  {
   "task": "Courier laptop and headset",
   "owner": "IT",
   "offset": -4
  }
 ],
 "onsite": [
  {
   "task": "Set up desk, laptop and access card",
   "owner": "IT",
   "offset": -1
  }
 ]
};
// ---- input normaliser (works for Webhook, Form, WhatsApp, Gmail, Sheets and sample data)
const input = $input.all().flatMap(i => {
  const j = i.json || {};
  if (j.messages && Array.isArray(j.messages)) {           // WhatsApp Trigger
    return j.messages.filter(m => m.text).map(m => ({ from: '+' + m.from, text: m.text.body }));
  }
  if (j.Subject !== undefined || j.From !== undefined) {     // Gmail Trigger (simple)
    return [{ from: (j.From || '').replace(/.*<|>.*/g, ''), subject: j.Subject || '', body: j.snippet || j.text || '' }];
  }
  const b = (j.body !== undefined && j.headers !== undefined) ? j.body : j;   // Webhook wraps payload in body
  if (Array.isArray(b)) return b;
  if (b && Array.isArray(b.items)) return b.items;
  return [b];
});

const addBiz = (d, n) => { d = new Date(d); const s = n >= 0 ? 1 : -1; while (n) { d.setUTCDate(d.getUTCDate() + s); const w = d.getUTCDay(); if (w !== 0 && w !== 6) n -= s; } return d; };
const out = [];
for (const h of input) {
  const start = new Date(h.start_date + 'T00:00:00Z');
  const tasks = [...TEMPLATES.common, ...(TEMPLATES.department[h.department] || []), ...TEMPLATES[h.remote ? 'remote' : 'onsite']];
  for (const t of tasks) out.push({ route: 'task', hire: h.name, task: t.task.replace('{name}', h.name),
    owner: t.owner === 'manager' ? h.manager : t.owner, due: addBiz(start, t.offset).toISOString().slice(0, 10), status: 'pending' });
  out.push({ route: 'welcome', hire: h.name, email: (h.email || h.name.split(' ')[0].toLowerCase() + '@yourcompany.com'),
    message: `Hi ${h.name.split(' ')[0]}, welcome to the team! On ${h.start_date} ${h.remote ? 'join the 9am video call in your inbox' : 'please arrive at 9am at reception'}. ${h.manager} will be your manager.` });
}
return out.map(json => ({ json }));
